int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *assoc;
    struct socket *new_sk = NULL;
    int ret = -EINVAL;

    if (!sk || !sockp)
        return -EINVAL;

    assoc = sctp_id2assoc(sk, id);
    if (!assoc)
        return -ENOENT;

    if (!assoc->peer_supports_sack || !assoc->sctp_ep || !assoc->sctp_ep->base.sk)
        return -EINVAL;

    new_sk = sock_alloc();
    if (!new_sk) {
        ret = -ENOMEM;
        goto out;
    }

    if (sock_init_data(new_sk, assoc->sctp_ep->base.sk) < 0) {
        ret = -ENOMEM;
        goto out;
    }

    if (sctp_association_migrate(assoc, new_sk) < 0) {
        ret = -EFAULT;
        goto out;
    }

    *sockp = new_sk;
    ret = 0;

out:
    if (ret < 0 && new_sk) {
        sock_release(new_sk);
        *sockp = NULL;
    }
    return ret;
}
